import{_ as e,o as a,c as s,ah as n}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Administrator","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/index.md","filePath":"src/en/guide/admin/index.md"}'),i={name:"en/guide/admin/index.md"};function r(d,t,o,c,l,h){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="administrator" tabindex="-1">Administrator <a class="header-anchor" href="#administrator" aria-label="Permalink to &quot;Administrator&quot;">​</a></h1><p>As an administrator, you have access to your school&#39;s entire structure: base configuration, staff, students, pricing, timetables, and report cards. It&#39;s ERA&#39;s most complete role — most other roles (teacher, front office, cashier...) work within a scope you&#39;ve set up beforehand.</p><h2 id="where-to-find-the-admin-tools" tabindex="-1">Where to find the admin tools <a class="header-anchor" href="#where-to-find-the-admin-tools" aria-label="Permalink to &quot;Where to find the admin tools&quot;">​</a></h2><p>The spaces column, on the left, is organised by domain; each space shows its pages as tabs at the top of the screen (see <a href="/en/guide/prise-en-main.html#finding-your-way-around">Finding your way around</a>). The screens you use day to day are at the top:</p><ul><li><strong>Students &amp; admissions</strong>: students, new applications, the applications queue and site transfers.</li><li><strong>Teaching</strong> and <strong>School life</strong>: timetables, attendance, discipline and extracurricular attendance.</li><li><strong>Student services</strong>: cafeteria, transport, boarding and infirmary.</li><li><strong>Finances</strong>: billing and expenses.</li><li><strong>Staff</strong>: employees, leave requests and staff transfers.</li></ul><p>The setup screens, opened less often, sit in two separate spaces at the bottom of the column:</p><ul><li><strong>School setup</strong>: academic years and periods, sites, departments, classes, subjects, subjects by department, teacher assignments, evaluation types, competencies, fee structures, transport routes, extracurricular activities and sessions.</li><li><strong>Administration</strong>: users, activity log, <a href="/en/guide/admin/page-accueil.html">Homepage</a> and <a href="/en/guide/admin/parametres-application.html">App settings</a>.</li></ul><p>The <strong>School setup</strong> space holds many pages: scroll its tabs sideways to see them all.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guide page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/en/guide/admin/tableau-de-bord.html">Dashboard</a></td><td>The school&#39;s management indicators (headcount, results, absence rate, cash flow) and how to export them</td></tr><tr><td><a href="/en/guide/admin/structure-etablissement.html">School structure</a></td><td>Academic years, periods, sites, departments, classes, subjects, competency frameworks, and evaluation types — the base setup to do at the start of the year</td></tr><tr><td><a href="/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a></td><td>Creating accounts and assigning them a role, managing staff records and contracts, assigning teachers, handling site transfer requests</td></tr><tr><td><a href="/en/guide/admin/eleves-tuteurs.html">Students and guardians</a></td><td>Student records, student and guardian accounts, specialty subject choices</td></tr><tr><td><a href="/en/guide/admin/frais-tarification.html">Fees and pricing</a></td><td>Fee structures per site/department/year and discounts granted to students</td></tr><tr><td><a href="/en/guide/admin/emplois-du-temps.html">Timetables</a></td><td>Building each class&#39;s weekly timetable</td></tr><tr><td><a href="/en/guide/admin/bulletins.html">Report cards</a></td><td>Publishing and downloading a class&#39;s report cards for a given period</td></tr><tr><td><a href="/en/guide/admin/activites-extrascolaires.html">Extracurricular activities</a></td><td>Building the extracurricular activity catalog and scheduling its sessions</td></tr><tr><td><a href="/en/guide/admin/page-accueil.html">Homepage</a></td><td>Configuring the school&#39;s public page: tagline, introduction, departments and FAQ</td></tr><tr><td><a href="/en/guide/admin/parametres-application.html">App settings</a></td><td>Identity, colors, logos, receipt customisation, and the two settings that change how the app behaves</td></tr><tr><td><a href="/en/guide/admin/demo-et-journal.html">Full demo and activity log</a></td><td>Activating the full demo (Era Admission tenants on the free tier) and reviewing the action history</td></tr></tbody></table><p>Settings that relate to your own account (profile, security, notifications, language) are shared by all roles — see <a href="/en/guide/prise-en-main.html">Getting started</a>.</p>',11)])])}const p=e(i,[["render",r]]);export{m as __pageData,p as default};
